static void test_init(TestData *d)

{

    QPCIBus *bus;

    QTestState *qs;

    char *s;



    s = g_strdup_printf("-machine q35 %s %s",

                        d->noreboot ? "" : "-global ICH9-LPC.noreboot=false",

